package com.shazwan.idash3;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.security.*;
/** Checks every bundled artwork/hash, bounded decoding, shared references, mapping and icon-only rail. */
public class Ios26IconChecks extends Instrumentation {
 LauncherActivity a;int count;
 void check(boolean value,String why){if(!value)throw new AssertionError(why);count++;}
 void ui(Runnable work){Throwable[] error={null};runOnMainSync(()->{try{work.run();}catch(Throwable t){error[0]=t;}});waitForIdleSync();if(error[0]!=null)throw new AssertionError(error[0]);}
 byte[] read(String path)throws Exception{try(InputStream in=getTargetContext().getAssets().open(path);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toByteArray();}}
 public void onCreate(Bundle args){super.onCreate(args);start();}
 public void onStart(){Bundle out=new Bundle();int code=Activity.RESULT_CANCELED;try{
  Context c=getTargetContext();JSONObject provenance=new JSONObject(new String(read("icons/ios26/provenance.json"),"UTF-8"));JSONObject entries=provenance.getJSONObject("entries");check(entries.length()==57,"all 57 iOS26 icons present");
  java.util.Iterator<String> names=entries.keys();while(names.hasNext()){String name=names.next();byte[] raw=read("icons/ios26/"+name+".png");StringBuilder hash=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(raw))hash.append(String.format(java.util.Locale.ROOT,"%02x",b&255));check(hash.toString().equals(entries.getJSONObject(name).getString("sha256")),"upstream bytes "+name);Bitmap icon=Ios26Icons.named(c,name);check(icon!=null&&icon.getWidth()==96&&icon.getHeight()==96,"bounded decode "+name);check(Ios26Icons.cacheBytes()<=Ios26Icons.CACHE_BYTES,"cache stays within budget");}
  check(Ios26Icons.match(c,"com.google.android.gm/.ConversationListActivityGmail","Gmail").endsWith("gmail"),"Gmail exact/package mapping");check(Ios26Icons.match(c,"com.google.android.apps.maps/.MapsActivity","Maps").endsWith("google_maps"),"Google Maps stays distinct from stock Maps");check("maps".equals(Ios26Icons.match(c,"com.waze/.Main","Waze")),"unmapped navigation category uses Maps");check(Ios26Icons.match(c,"example.canbus/.Main","CANBUS")==null,"unsupported car tool retains original renderer");check(Ios26Icons.named(c,"missing_test_asset")==null,"missing asset safe fallback");
  Bitmap retained=Ios26Icons.named(c,"phone");check(Ios26Icons.named(c,"phone")==retained,"reuses decoded artwork");Ios26Icons.clear();check(!retained.isRecycled()&&Ios26Icons.cacheBytes()==0,"cache trim keeps active view references safe");
  BitmapFactory.Options sample=new BitmapFactory.Options();sample.inSampleSize=2;Bitmap original=BitmapFactory.decodeByteArray(read("icons/ios26/ios26_lg_chrome.png"),0,read("icons/ios26/ios26_lg_chrome.png").length,sample),vivid=Ios26Icons.named(c,"chrome");boolean changed=false,alphaSame=true;for(int y=0;y<vivid.getHeight();y++)for(int x=0;x<vivid.getWidth();x++){int before=original.getPixel(x,y),after=vivid.getPixel(x,y);if(Color.alpha(before)>128&&(before&0xffffff)!=(after&0xffffff))changed=true;if(Color.alpha(before)!=Color.alpha(after))alphaSame=false;}check(changed,"vivid renderer changes RGB from pastel source");check(alphaSame,"vivid renderer preserves source opacity");original.recycle();
  a=(LauncherActivity)startActivitySync(new Intent(c,LauncherActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));java.util.concurrent.CountDownLatch ready=new java.util.concurrent.CountDownLatch(1);a.worker.execute(()->a.main.post(ready::countDown));check(ready.await(45,java.util.concurrent.TimeUnit.SECONDS),"catalog ready");waitForIdleSync();
  ui(()->{a.page="road";a.drivingTab=0;a.render();LinearLayout rail=(LinearLayout)a.drivingWorkspace.getChildAt(0);check(rail.getChildCount()==5,"clock and four rail controls");for(int i=1;i<=4;i++){View hit=rail.getChildAt(i);check(hit instanceof FrameLayout&&hit.isFocusable()&&hit.getContentDescription()!=null,"rail is an accessible icon control");check(((FrameLayout)hit).getChildCount()==1,"single icon per rail control");if(i<4)check(((FrameLayout)hit).getChildAt(0) instanceof ImageView,"pack image used for map/media/phone");}a.onTrimMemory(android.content.ComponentCallbacks2.TRIM_MEMORY_RUNNING_LOW);check(Ios26Icons.cacheBytes()==0,"memory pressure trims icon cache");});
  Bitmap screenshot=getUiAutomation().takeScreenshot();if(screenshot!=null){try(OutputStream file=new FileOutputStream(new File(a.getFilesDir(),"ios26-workspace.png"))){screenshot.compress(Bitmap.CompressFormat.PNG,100,file);}screenshot.recycle();}
  out.putString("stream","PASS: "+count+" iOS26 icon assertions\n");code=Activity.RESULT_OK;
 }catch(Throwable t){out.putString("stream","FAIL after "+count+": "+t+"\n");}finally{if(a!=null)ui(a::finish);}finish(code,out);}
}
